		Type {string} 类型
		WriteLog {bool} 是否记日志
		Quality* {int} 品质
		AuctionPrice {int} 竞拍底价
		Sort* {int} 排序
		LimitSaveLevel {int} 限制存档等级
		LimitDate {array(array(int, int...), ...)} 限制时间
		StackTime {int} 叠加时长
		StackUP* {int} 叠加上限
		EquipStar {int} 装备星数
		EquipPosition {int} 部位
		Attrs {array(array(number, number...), ...)} 增加属性
		EquipSynergy {int} 装备组合ID
		SkillBooks {array(array(int, int...), ...)} 技能书对应的技能ID
		PackRandomParams {array(int, int...)} 包随机参数
		NextQualityId {int} 下一个品质的ID(升品用)
		SoulAttrLibs {array(int, int...)} 魂器属性库
		FateMass {array(number, number...)} 气运重量
		ExpPillParams {array(int, int...)} 经验丹参数
		BlessParams {array(int, int...)} 祝福参数
		ActionParams {array(array(auto, auto...), ...)} 行为参数
		Dungeon {string} 使用副本限制
		Progress {int} 进度值
		AutoCombine {array(int, int...)} 一键合成
		Reward {array(array(int, int...), ...)} 奖励内容
		Particle {string} 相关特效
		NextStarID {int} 下一星ID
		ConvertID {int} 转换ID
		Optional {map{[auto] = auto}} 选择列表
		CheckHeroCount {int} 检查英雄数量
		Sell {array(array(int, int...), ...)} 出售获得

]]
